foreach($ps in @($baseModule,$liveModule,$userModule,$optimizer,$pruneOptimizer)){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($ps,[ref]$tokens,[ref]$errors);if(@($errors).Count){throw "$ps failed Windows PowerShell 5.1 parse: $(@($errors|ForEach-Object{$_.Message}) -join '; ')"};if($ps -in @($baseModule,$liveModule,$userModule)){foreach($v in @($ast.FindAll({param($n)$n -is [Management.Automation.Language.VariableExpressionAst]},$true))){if([string]::Equals([string]$v.VariablePath.UserPath,'Host',[StringComparison]::OrdinalIgnoreCase)){throw "Active platform presentation runtime references reserved `$Host: $ps line $($v.Extent.StartLineNumber)"}}}}
