$liveText=Get-Content -Raw $liveModule -Encoding UTF8;foreach($n in @('HUYMAIER_LIVE_PLATFORM_3D_HELPERS_V3','HUYMAIER_CONTEXT_AWARE_MODEL_VIEWER_V1','HuymaierLiveModel3D.dll','Initialize-HcLiveModelAssembly','New-HcLiveModelView','Open-HcPlatformModelViewer','Close-HcPlatformModelViewer','function Invoke-SecondaryAction','function Apply-ControllerNavigation')){if(-not$liveText.Contains($n)){throw "Live helper V3 contract missing: $n"}};foreach($bad in @('function New-PlatformCard','function Add-PlatformRail','Set-HcAtlasFallbackVisual','HuymaierPlatformAtlas')){if($liveText.Contains($bad)){throw "Live helper still owns retired presentation: $bad"}}
$userText=Get-Content -Raw $userModule -Encoding UTF8;foreach($n in @('HUYMAIER_USER_3D_MODELS_RUNTIME_V6','HUYMAIER_3D_DUAL_SHELF_RUNTIME_V1','HUYMAIER_3D_TEXTURED_BOUNDED_RESIDENCY_V2','Providers','Consoles','Test-HcStorefrontPlatform','maxTextureResidency=4')){if(-not$userText.Contains($n)){throw "V6 presentation owner contract missing: $n"}}
$loaderText=Get-Content -Raw $modelLoader -Encoding UTF8;foreach($n in @('HUYMAIER_GLTF_MATERIAL_COMPAT_V2','KHR_texture_transform','KHR_materials_emissive_strength','KHR_materials_pbrSpecularGlossiness','KHR_materials_specular','KHR_materials_clearcoat','alphaMode','sampler','ImageCache')){if(-not$loaderText.Contains($n)){throw "GLB material compatibility contract missing: $n"}}
$controlText=Get-Content -Raw $liveControl -Encoding UTF8;foreach($n in @('HUYMAIER_ROTATION_SAFE_MODEL_FRAMING_V2','public sealed class LiveModelView','Viewport3D','SetScalePercent','Rotate(double yawDelta','MaterialCount','TextureCount','ImageCount','boundingDiameter')){if(-not$controlText.Contains($n)){throw "Live control V6 contract missing: $n"}}
$map=Get-Content -Raw $modelMap -Encoding UTF8|ConvertFrom-Json;if([int]$map.schemaVersion-ne2){throw '3D model map schema version must remain 2.'};if($null-eq$map.sourceModels){throw '3D model map no longer contains original source-model provenance.'}
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml,System.Web.Extensions
