$tempRoot=$(if($env:RUNNER_TEMP){$env:RUNNER_TEMP}else{[IO.Path]::GetTempPath()});$temp=Join-Path $tempRoot ('hc-platform-v6-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force -Path $temp|Out-Null
try{$refs=@([Uri].Assembly.Location,[Linq.Enumerable].Assembly.Location,[Web.Script.Serialization.JavaScriptSerializer].Assembly.Location,[Windows.DependencyObject].Assembly.Location,[Windows.Media.Visual].Assembly.Location,[Windows.Window].Assembly.Location,[System.Xaml.XamlReader].Assembly.Location)|Select-Object -Unique;$dll=Join-Path $temp 'HuymaierLiveModel3D.dll';$args=@('/noconfig','/nologo','/target:library','/platform:x64','/optimize+',('/out:'+$dll));foreach($r in $refs){$args+=('/reference:'+$r)};$args+=@($modelLoader,$modelAliases,$liveControl);& $csc @args;if($LASTEXITCODE-ne0-or-not(Test-Path $dll)){throw 'V6 live platform-model x64 DLL compile failed.'};$bytes=[IO.File]::ReadAllBytes($dll);$pe=[BitConverter]::ToInt32($bytes,0x3C);$machine=[BitConverter]::ToUInt16($bytes,$pe+4);if($machine-ne0x8664){throw 'HuymaierLiveModel3D.dll is not x64.'}
$core=Join-Path $temp 'HuymaierConsole.ps1';$bootstrap=Join-Path $temp 'HuymaierBootstrap.ps1';$installer=Join-Path $temp 'Install-HuymaierConsole.ps1';$builder=Join-Path $temp 'Build-HuymaierReleaseCandidate.Core.ps1';Copy-Item (Join-Path $root 'HuymaierConsole.ps1') $core;Copy-Item (Join-Path $root 'HuymaierBootstrap.ps1') $bootstrap;Copy-Item (Join-Path $root 'Install-HuymaierConsole.ps1') $installer;Copy-Item (Join-Path $root '.build\Build-HuymaierReleaseCandidate.Core.ps1') $builder;& $optimizer -CorePath $core -BootstrapPath $bootstrap -InstallerScriptPath $installer -CoreBuilderPath $builder;& $pruneOptimizer -CoreBuilderPath $builder;foreach($ps in @($core,$bootstrap,$installer,$builder)){$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($ps,[ref]$t,[ref]$e);if(@($e).Count){throw "Transformed platform-model file failed parse: $ps :: $(@($e|ForEach-Object{$_.Message}) -join '; ')"}};$coreText=Get-Content -Raw $core;$bootstrapText=Get-Content -Raw $bootstrap;$installerText=Get-Content -Raw $installer;$builderText=Get-Content -Raw $builder;foreach($n in @('HUYMAIER_PLATFORM_3D_MODELS_RUNTIME_V2','HUYMAIER_USER_3D_MODELS_RUNTIME_LOAD_V1','HuymaierUser3DModels.ps1','HuymaierLivePlatformModels.ps1')){if(-not$coreText.Contains($n)){throw "Transformed core contract missing: $n"}};if($bootstrapText.Contains('HuymaierPlatformAtlas.ps1')-or$installerText.Contains('HuymaierPlatformAtlas.ps1')){throw 'Retired atlas runtime survived bootstrap/installer transform.'};foreach($n in @('HuymaierLiveModel3D.dll','HUYMAIER_RETIRED_3D_PAYLOAD_PRUNE_V1','HuymaierModelPreviewWorker.exe','Assets\Models\Live')){if(-not$builderText.Contains($n)){throw "Staged builder/prune contract missing: $n"}}}finally{Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue}
